CREATE TABLE cash_journal_corrections (
 id TEXT PRIMARY KEY NOT NULL, entry_id TEXT NOT NULL REFERENCES cash_entries(id), journal_id TEXT NOT NULL UNIQUE REFERENCES journal_entries(id), predecessor_reversal_id TEXT NOT NULL UNIQUE REFERENCES journal_entries(id), created_by TEXT NOT NULL REFERENCES "user"(id), request_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER cash_correction_link BEFORE INSERT ON cash_journal_corrections BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM cash_entry_voids WHERE entry_id=NEW.entry_id) THEN RAISE(ABORT,'unauthorized or source void') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j JOIN journal_entries r ON r.id=NEW.predecessor_reversal_id AND r.status='posted' JOIN journal_entries p ON p.id=r.reverses_entry_id AND p.status='posted' JOIN cash_entries e ON e.id=NEW.entry_id WHERE j.id=NEW.journal_id AND j.status='draft' AND j.source_type='cash-entry-correction' AND j.source_id=NEW.request_key AND j.created_by=NEW.created_by AND j.reverses_entry_id IS NULL AND j.currency=p.currency AND j.currency=e.currency AND j.effective_date>=r.effective_date AND ((p.source_type='cash-entry' AND p.source_id=e.id) OR EXISTS(SELECT 1 FROM cash_journal_corrections c WHERE c.entry_id=e.id AND c.journal_id=p.id))) THEN RAISE(ABORT,'invalid predecessor or correction date') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM journal_entries j WHERE ((j.source_type='cash-entry' AND j.source_id=NEW.entry_id) OR EXISTS(SELECT 1 FROM cash_journal_corrections c WHERE c.entry_id=NEW.entry_id AND c.journal_id=j.id)) AND (j.status='draft' OR (j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries r WHERE r.reverses_entry_id=j.id AND r.status='posted')))) THEN RAISE(ABORT,'source has active journal') END;
END;
CREATE TRIGGER cash_correction_post BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='cash-entry-correction' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM cash_journal_corrections c JOIN cash_entries e ON e.id=c.entry_id JOIN journal_entries r ON r.id=c.predecessor_reversal_id AND r.status='posted' JOIN app_user_roles a ON a.user_id=NEW.created_by AND a.role='admin' WHERE c.journal_id=NEW.id AND c.created_by=NEW.created_by AND c.request_key=NEW.source_id AND NEW.reverses_entry_id IS NULL AND NEW.effective_date>=r.effective_date AND NEW.currency=e.currency AND NOT EXISTS(SELECT 1 FROM cash_entry_voids v WHERE v.entry_id=e.id) AND (length(e.amount_minor)<16 OR (length(e.amount_minor)=16 AND e.amount_minor<='9007199254740991')) AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id)=2 AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id AND side='debit' AND CAST(amount_minor AS TEXT)=e.amount_minor)=1 AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND CAST(amount_minor AS TEXT)=e.amount_minor)=1 AND (SELECT count(DISTINCT account_id) FROM journal_lines WHERE entry_id=NEW.id)=2) THEN RAISE(ABORT,'correction must match active source') END;
END;
CREATE TRIGGER cash_correction_draft_immutable BEFORE UPDATE ON journal_entries WHEN EXISTS(SELECT 1 FROM cash_journal_corrections WHERE journal_id=OLD.id) AND (NEW.id IS NOT OLD.id OR NEW.currency IS NOT OLD.currency OR NEW.effective_date IS NOT OLD.effective_date OR NEW.description IS NOT OLD.description OR NEW.source_type IS NOT OLD.source_type OR NEW.source_id IS NOT OLD.source_id OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR NEW.reverses_entry_id IS NOT OLD.reverses_entry_id) BEGIN SELECT RAISE(ABORT,'correction journal metadata immutable'); END;
CREATE TRIGGER cash_correction_reversal BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='cash-correction-reversal' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NEW.reverses_entry_id IS NOT NEW.source_id OR NOT EXISTS(SELECT 1 FROM cash_journal_corrections c JOIN journal_entries j ON j.id=c.journal_id WHERE j.id=NEW.source_id AND j.status='posted') THEN RAISE(ABORT,'invalid correction reversal') END; END;
CREATE TRIGGER cash_correction_void BEFORE INSERT ON cash_entry_voids WHEN EXISTS(SELECT 1 FROM cash_journal_corrections c JOIN journal_entries j ON j.id=c.journal_id WHERE c.entry_id=NEW.entry_id AND (j.status='draft' OR (j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries r WHERE r.reverses_entry_id=j.id AND r.status='posted' AND r.effective_date<=date('now'))))) BEGIN SELECT RAISE(ABORT,'correction must be reversed and effective before void'); END;
CREATE TRIGGER cash_correction_no_update BEFORE UPDATE ON cash_journal_corrections BEGIN SELECT RAISE(ABORT,'correction history immutable'); END;
CREATE TRIGGER cash_correction_no_delete BEFORE DELETE ON cash_journal_corrections BEGIN SELECT RAISE(ABORT,'correction history immutable'); END;
